<script setup lang="ts">
import { computed } from 'vue'
import { groupedDays } from './types'
import PhotoGallery from './PhotoGallery.vue'
const props=defineProps<{article:any;selected?:string|null}>(),emit=defineEmits<{(e:'select',id:string):void}>()
const groups=computed(()=>groupedDays(props.article.life?.activities||[]))
function photos(a:any){return props.article.media.filter((p:any)=>a.media_ids.includes(p.id))}
</script>
<template><div v-if="groups.length" class="trip-view"><p class="trip-range">{{article.life.start_date||'起始待定'}} — {{article.life.end_date||'结束待定'}}</p><section v-for="g in groups" :key="g.day" class="trip-day"><h3>{{g.day}}</h3><ol><li v-for="a in g.items" :key="a.id" :class="{'activity-selected':a.place_id&&selected===a.place_id}" :data-activity="a.id"><span class="activity-time">{{a.time||'时间未定'}}</span><h4>{{a.title}}</h4><p v-if="a.kind&&a.kind!=='other'" class="muted">{{({food:'美食',sight:'景点',transport:'交通'} as Record<string,string>)[a.kind]}}</p><section v-if="a.kind==='food'" class="food-memory"><p v-if="a.dish">菜品 · {{a.dish}}</p><p v-if="a.price!=null">{{a.currency||'金额'}} {{a.price}}</p><p v-if="a.rating!=null">评分 {{a.rating}} / 5</p><p v-if="a.experience" class="plain-value">{{a.experience}}</p></section><p v-if="a.experience_id"><a v-if="article.experiences?.find((e:any)=>e.id===a.experience_id)?.active" :href="'#entry-'+a.experience_id">交通：{{article.experiences?.find((e:any)=>e.id===a.experience_id)?.name||'正文交通卡片'}}</a><span v-else>交通卡片已从正文移除，历史关联保留。</span></p><p class="plain-value">{{a.description}}</p><button v-if="a.place_id" class="activity-place" :aria-pressed="selected===a.place_id" @click="emit('select',a.place_id)">{{article.places.find((p:any)=>p.id===a.place_id)?.name||'关联地点'}} · 在地图中查看</button><PhotoGallery v-if="photos(a).length" :photos="photos(a)" /></li></ol></section></div><p v-else class="trip-empty">行程尚未安排，地点和故事仍可阅读。</p></template>
<style scoped>
.trip-range{color:var(--reader-accent,var(--accent))}.trip-day{margin:32px 0}.trip-day ol{list-style:none;border-left:2px solid var(--reader-border,var(--line));padding:0 0 0 20px}.trip-day li{padding:20px;border:1px solid var(--reader-border,var(--line));border-radius:var(--radius);margin:20px 0;background:var(--reader-card-background,var(--surface));overflow-wrap:anywhere}.trip-day li.activity-selected{outline:2px solid var(--reader-accent,var(--accent));outline-offset:3px}.trip-day h4{font:600 24px var(--heading);margin:10px 0}.activity-time{color:var(--reader-accent,var(--accent));font-size:14px}.activity-place{margin:10px 0 20px}.trip-day .plain-value{white-space:pre-wrap}@media(max-width:600px){.trip-day ol{padding-left:12px}.trip-day li{padding:14px}}
</style>
